using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpServer;

[McpServerToolType]
public class ApiTool(HttpClient httpClient)
{
    [McpServerTool, Description("Fetches data from an external API endpoint and returns the response body.")]
    public async Task<string> FetchApi(
        [Description("The full URL to fetch (e.g. https://api.example.com/data)")] string url,
        CancellationToken cancellationToken = default)
    {
        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using ModelContextProtocol.Server;
using ModelContextProtocol;
using System.ComponentModel;

namespace McpServer;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt that asks for a concise summary of the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize")] string content,
        [Description("Optional desired length (e.g. '2 sentences', 'one paragraph')")] string? length = null)
    {
        var instruction = length is not null
            ? $"Summarize the following text in {length}:"
            : "Summarize the following text concisely:";

        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content { Type = "text", Text = $"{instruction}\n\n{content}" }
            }
        ];
    }
}

